      "path": "src/frontend/src",
      "summary": "Groups the application source under the Next.js App Router."
    },
    {
      "path": "src/frontend/src/app",
      "summary": "Root layout and home page for the backend health check.",
      "interface": [
        "`RootLayout` renders route content within an English-language HTML document. `metadata` sets the page title and favicon. [layout.tsx:RootLayout] [layout.tsx:metadata]",
