    {
      "path": "src/backend/src",
      "summary": "Backend source sets. The production directory links to the Java application and runtime configuration."
    },
    {
      "path": "src/backend/src/main",
      "summary": "Production Java source and Spring Boot runtime configuration.",
      "interface": [
        "The runtime configuration sets port 8080 and lists health and info in the Actuator web exposure configuration. [resources/application.yml:server.port] [resources/application.yml:management.endpoints.web.exposure.include]"
      ]
    },
    {
      "path": "src/backend/src/main/java",
      "summary": "Production Java source root."
