    {
      "path": "src/backend/src/main/java/com",
      "summary": "First segment of the Java package hierarchy."
    },
    {
      "path": "src/backend/src/main/java/com/global",
      "summary": "Java namespace containing the com.global.ct packages."
    },
    {
      "path": "src/backend/src/main/java/com/global/ct",
      "summary": "Java namespace containing the frame inventory application package."
    },
    {
      "path": "src/backend/src/main/java/com/global/ct/frameinventory",
      "summary": "Spring Boot entry point and custom HTTP health controller.",
      "interface": [
        "Application.main starts the application. [Application.java:main]",
        "GET /api/health returns status, service name, and timestamp. [HealthController.java:health]"
      ],
      "invariants": [
