        status=$(docker inspect --format '{{.State.Status}}' "$app")
        if docker logs "$app" 2>&1 | grep -F "$1" >/dev/null; then return; fi
        if [[ "$status" == exited ]]; then break; fi
        sleep 1
    done
    docker logs "$app"
    return 1
}
await_backend 'Started Application'
docker logs "$app" 2>&1 | grep -E 'Flyway|Migrat|Successfully applied'
run_sql() {
    docker exec -i "$db" psql -X -v ON_ERROR_STOP=1 -U app -d frames "$@"
}
[[ "$(run_sql -Atc 'SELECT version FROM flyway_schema_history WHERE success;')" == 1 ]]
run_sql < /private/tmp/frame-schema-verify.0kvdNbqd/constraints.sql
run_sql < /private/tmp/frame-schema-verify.0kvdNbqd/fixture.sql
docker restart "$app" >/dev/null
await_backend 'No migration necessary'
[[ "$(run_sql -Atc 'SELECT count(*) FROM flyway_schema_history;')" == 1 ]]
printf '%s\n' 'Flyway applied V1 and restart retained one migration entry.'
SH
cat > /private/tmp/frame-schema-verify.0kvdNbqd/constraints.sql <<'SQL'
BEGIN;
INSERT INTO frame VALUES ('FRM-TEST');
INSERT INTO frame_version (frame_id, valid_from, source_modified_at, status)
VALUES ('FRM-TEST', '2026-01-01T00:00:00Z', '2025-12-01 00:00:00', 'DRAFT');

DO $$
DECLARE
    violated text;
BEGIN
    BEGIN
        INSERT INTO frame_version (frame_id, valid_from, status)
        VALUES ('FRM-TEST', '2026-01-02T00:00:00Z', 'LIVE');
        RAISE EXCEPTION 'Two active versions were accepted';
    EXCEPTION WHEN unique_violation THEN
        GET STACKED DIAGNOSTICS violated = CONSTRAINT_NAME;
        IF violated <> 'frame_version_one_current_idx' THEN RAISE; END IF;
    END;
    BEGIN
        UPDATE frame_version SET is_current = false WHERE frame_id = 'FRM-TEST';
        RAISE EXCEPTION 'An inactive version without an end time was accepted';
    EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS violated = CONSTRAINT_NAME;
        IF violated <> 'frame_version_current_matches_validity' THEN RAISE; END IF;
    END;
    BEGIN
        UPDATE frame_version SET is_current = false, valid_to = valid_from WHERE frame_id = 'FRM-TEST';
        RAISE EXCEPTION 'A zero-length interval was accepted';
    EXCEPTION WHEN check_violation THEN
        GET STACKED DIAGNOSTICS violated = CONSTRAINT_NAME;
        IF violated <> 'frame_version_positive_validity' THEN RAISE; END IF;
    END;
    BEGIN
        INSERT INTO frame_version (frame_id, valid_from, status)
        VALUES ('UNKNOWN-FRAME', '2026-01-02T00:00:00Z', 'LIVE');
        RAISE EXCEPTION 'An orphan version was accepted';
    EXCEPTION WHEN foreign_key_violation THEN
        NULL;
    END;
END $$;

UPDATE frame_version SET is_current = false, valid_to = '2026-01-02T00:00:00Z'
WHERE frame_id = 'FRM-TEST' AND is_current;
INSERT INTO frame_version (frame_id, valid_from, source_modified_at, status)
VALUES ('FRM-TEST', '2026-01-02T00:00:00Z', '2025-12-01 00:00:00', 'LIVE');
DO $$
BEGIN
    IF (SELECT count(*) FROM frame_version WHERE frame_id = 'FRM-TEST') <> 2 THEN
        RAISE EXCEPTION 'Close and append did not preserve history';
    END IF;
    IF (SELECT count(*) FROM frame_version WHERE frame_id = 'FRM-TEST' AND is_current) <> 1 THEN
        RAISE EXCEPTION 'Expected one current version';
    END IF;
END $$;
ROLLBACK;
SQL

