#!/bin/bash
set -euo pipefail
label="frame-schema-verify-$(uuidgen | tr '[:upper:]' '[:lower:]' | cut -c1-8)"
network="$label"
db="$label-db"
app="$label-app"
image="$label:app"
build="$label:build"
cleanup() {
    docker rm -f "$app" "$db" >/dev/null 2>&1 || true
    docker network rm "$network" >/dev/null 2>&1 || true
}
trap cleanup EXIT
docker build --target build -t "$build" src/backend
docker run --rm "$build" ./gradlew --no-daemon test
docker build -t "$image" src/backend
docker network create "$network" >/dev/null
docker run -d --name "$db" --network "$network" -e POSTGRES_DB=frames -e POSTGRES_USER=app -e POSTGRES_PASSWORD=REDACTED --tmpfs /var/lib/postgresql postgres:18.6 >/dev/null
for ((attempt=1; attempt<=45; attempt++)); do
    if docker exec "$db" pg_isready -q -h 127.0.0.1 -U app -d frames; then break; fi
    sleep 1
done
docker exec "$db" pg_isready -h 127.0.0.1 -U app -d frames
docker run -d --name "$app" --network "$network" -e "SPRING_DATASOURCE_URL=jdbc:postgresql://$db:5432/frames" "$image" >/dev/null
await_backend() {
    for ((attempt=1; attempt<=60; attempt++)); do
        status=$(docker inspect --format '{{.State.Status}}' "$app")
        if docker logs "$app" 2>&1 | grep -F "$1" >/dev/null; then return; fi
        if [[ "$status" == exited ]]; then break; fi
        sleep 1
    done
    docker logs "$app"
    return 1
}
await_backend 'Started Application'
docker logs "$app" 2>&1 | grep -E 'Flyway|Migrat|Successfully applied'
run_sql() {
    docker exec -i "$db" psql -X -v ON_ERROR_STOP=1 -U app -d frames "$@"
}
[[ "$(run_sql -Atc 'SELECT version FROM flyway_schema_history WHERE success;')" == 1 ]]
run_sql < /private/tmp/frame-schema-verify.0kvdNbqd/constraints.sql
run_sql < /private/tmp/frame-schema-verify.0kvdNbqd/fixture.sql
docker restart "$app" >/dev/null
await_backend 'No migration necessary'
[[ "$(run_sql -Atc 'SELECT count(*) FROM flyway_schema_history;')" == 1 ]]
printf '%s\n' 'Flyway applied V1 and restart retained one migration entry.'
SH
